import AccessorArray = require( '@stdlib/array/base/accessor' );
import gassignDiagonal = require( './index' );


// TESTS //

// The function returns a collection...
{
	const A = new Float64Array( 6 );
	const x = new Float64Array( 2 );

	gassignDiagonal( 'row-major', 2, 3, 0, x, 1, A, 3 ); // $ExpectType Collection<number>
	gassignDiagonal( 'row-major', 2, 3, 0, new AccessorArray( x ), 1, new AccessorArray( A ), 3 ); // $ExpectType AccessorArrayLike<number>
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	const A = new Float64Array( 6 );
	const x = new Float64Array( 2 );

	gassignDiagonal( 10, 2, 3, 0, x, 1, A, 3 ); // $ExpectError
	gassignDiagonal( true, 2, 3, 0, x, 1, A, 3 ); // $ExpectError
	gassignDiagonal( null, 2, 3, 0, x, 1, A, 3 ); // $ExpectError
	gassignDiagonal( undefined, 2, 3, 0, x, 1, A, 3 ); // $ExpectError
	gassignDiagonal( [], 2, 3, 0, x, 1, A, 3 ); // $ExpectError
	gassignDiagonal( {}, 2, 3, 0, x, 1, A, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	const A = new Float64Array( 6 );
	const x = new Float64Array( 2 );

	gassignDiagonal( 'row-major', '2', 3, 0, x, 1, A, 3 ); // $ExpectError
	gassignDiagonal( 'row-major', true, 3, 0, x, 1, A, 3 ); // $ExpectError
	gassignDiagonal( 'row-major', null, 3, 0, x, 1, A, 3 ); // $ExpectError
	gassignDiagonal( 'row-major', undefined, 3, 0, x, 1, A, 3 ); // $ExpectError
	gassignDiagonal( 'row-major', [], 3, 0, x, 1, A, 3 ); // $ExpectError
	gassignDiagonal( 'row-major', {}, 3, 0, x, 1, A, 3 ); // $ExpectError
}

