	gassignDiagonal( 'row-major', 2, 3, 0, x, 1, A, null ); // $ExpectError
	gassignDiagonal( 'row-major', 2, 3, 0, x, 1, A, undefined ); // $ExpectError
	gassignDiagonal( 'row-major', 2, 3, 0, x, 1, A, [] ); // $ExpectError
	gassignDiagonal( 'row-major', 2, 3, 0, x, 1, A, {} ); // $ExpectError
