// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const A = new Float64Array( 6 );
	const x = new Float64Array( 2 );

	gassignDiagonal(); // $ExpectError
	gassignDiagonal( 'row-major' ); // $ExpectError
	gassignDiagonal( 'row-major', 2 ); // $ExpectError
	gassignDiagonal( 'row-major', 2, 3 ); // $ExpectError
	gassignDiagonal( 'row-major', 2, 3, 0 ); // $ExpectError
	gassignDiagonal( 'row-major', 2, 3, 0, x ); // $ExpectError
	gassignDiagonal( 'row-major', 2, 3, 0, x, 1 ); // $ExpectError
	gassignDiagonal( 'row-major', 2, 3, 0, x, 1, A ); // $ExpectError
	gassignDiagonal( 'row-major', 2, 3, 0, x, 1, A, 3, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a collection...
{
	const A = new Float64Array( 6 );
	const x = new Float64Array( 2 );

	gassignDiagonal.ndarray( 2, 3, 0, x, 1, 0, A, 3, 1, 0 ); // $ExpectType Collection<number>
	gassignDiagonal.ndarray( 2, 3, 0, new AccessorArray( x ), 1, 0, new AccessorArray( A ), 3, 1, 0 ); // $ExpectType AccessorArrayLike<number>
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const A = new Float64Array( 6 );
	const x = new Float64Array( 2 );

	gassignDiagonal.ndarray( '2', 3, 0, x, 1, 0, A, 3, 1, 0 ); // $ExpectError
	gassignDiagonal.ndarray( true, 3, 0, x, 1, 0, A, 3, 1, 0 ); // $ExpectError
	gassignDiagonal.ndarray( null, 3, 0, x, 1, 0, A, 3, 1, 0 ); // $ExpectError
	gassignDiagonal.ndarray( undefined, 3, 0, x, 1, 0, A, 3, 1, 0 ); // $ExpectError
	gassignDiagonal.ndarray( [], 3, 0, x, 1, 0, A, 3, 1, 0 ); // $ExpectError
	gassignDiagonal.ndarray( {}, 3, 0, x, 1, 0, A, 3, 1, 0 ); // $ExpectError
}

