// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const A = new Float64Array( 6 );
	const x = new Float64Array( 2 );

	gassignDiagonal.ndarray(); // $ExpectError
	gassignDiagonal.ndarray( 2 ); // $ExpectError
	gassignDiagonal.ndarray( 2, 3 ); // $ExpectError
	gassignDiagonal.ndarray( 2, 3, 0 ); // $ExpectError
	gassignDiagonal.ndarray( 2, 3, 0, x ); // $ExpectError
	gassignDiagonal.ndarray( 2, 3, 0, x, 1 ); // $ExpectError
	gassignDiagonal.ndarray( 2, 3, 0, x, 1, 0 ); // $ExpectError
	gassignDiagonal.ndarray( 2, 3, 0, x, 1, 0, A ); // $ExpectError
	gassignDiagonal.ndarray( 2, 3, 0, x, 1, 0, A, 3 ); // $ExpectError
	gassignDiagonal.ndarray( 2, 3, 0, x, 1, 0, A, 3, 1 ); // $ExpectError
	gassignDiagonal.ndarray( 2, 3, 0, x, 1, 0, A, 3, 1, 0, 10 ); // $ExpectError
}
